 "content": "from collections import deque


def transform(grid):
    """Extend the four 1 markers as full row/column beams; recolor each hit 2-object."""
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) if any(grid[r][c] == 1 for c in range(w))}
    cols = {c for c in range(w) if any(grid[r][c] == 1 for r in range(h))}
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            component = []
            q = deque([(r, c)])
            seen.add((r, c))
            hit = False
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                hit |= rr in rows or cc in cols
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if hit:
                for rr, cc in component:
                    out[rr][cc] = 1
    for r in rows:
        for c in range(w):
            out[r][c] = 1
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    return out
